TypeScript example - async iterator streaming with final structured parse:

const client = new RedwoodClient({ apiKey: process.env.RW_API_KEY });
const req = client.chat.stream({ model: 'rwd-7b', messages: [{ role: 'user', content: 'Extract tasks from this note' }], schema: { type: 'object', properties: { tasks: { type: 'array', items: { type: 'string' } } } } });
for await (const evt of req) {
  if (evt.type === 'token') console.log('token', evt.data);
  if (evt.type === 'tool_call') console.log('tool requested', evt.tool.name, evt.tool.args);
  if (evt.type === 'done') {
     const parsed = client.parsers.jsonSafeParse(evt.structured);
     if (parsed.ok) console.log('parsed payload', parsed.value);
     else console.warn('fallback raw text', evt.text);
  }
}

Notes: also provide `request.stream(onToken, onTool, onDone)` for users preferring callbacks.

Python example - async generator + Pydantic model validation:

from redwood import RedwoodClient
from pydantic import BaseModel, ValidationError

class TaskList(BaseModel):
    tasks: list[str]

client = RedwoodClient(api_key=os.getenv('RW_API_KEY'))
stream = client.chat.stream(model='rwd-7b', messages=[{'role':'user','content':'List follow-ups'}], schema={'type':'object','properties':{'tasks':{'type':'array','items':{'type':'string'}}}})

async for event in stream:
    if event['type']=='token':
        print('tok', event['data'])
    if event['type']=='tool_call':
        # spawn tool worker or forward to infra
        print('TOOL', event['tool'])
    if event['type']=='done':
        try:
            parsed = TaskList.parse_raw(event['structured'])
            print('VALID', parsed.tasks)
        except ValidationError as e:
            print('validation failed, raw text fallback', event['text'])

Go example - channel-based stream and decoding into struct:

client := redwood.NewClient(redwood.Config{APIKey: os.Getenv("RW_API_KEY")})
req := client.ChatStream(redwood.ChatRequest{Model: "rwd-7b", Messages: []redwood.Message{{Role: "user", Content: "Summarize action items"}}})
for evt := range req.Events() {
    switch evt.Type {
    case redwood.StreamEventToken:
        fmt.Print(evt.Token)
    case redwood.StreamEventToolCall:
        go handleTool(evt.Tool) // concurrent tool worker
    case redwood.StreamEventDone:
        var payload struct{ Tasks []string \`json:"tasks"\` }
        if err := json.Unmarshal([]byte(evt.Structured), &payload); err != nil {
            fmt.Println("parse error, raw:", evt.Text)
        } else {
            fmt.Println("tasks:", payload.Tasks)
        }
    }
}
